    "chat": "<path d=\"M4 5.5A1.5 1.5 0 0 1 5.5 4h9A1.5 1.5 0 0 1 16 5.5v6a1.5 1.5 0 0 1-1.5 1.5H9.25L6 15.75V13h-.5A1.5 1.5 0 0 1 4 11.5z\"/>",
    "check": "<path d=\"m4.5 10.5 3.5 3.5 7.5-8\"/>",
