    "flask": "<path d=\"M8 3.25h4\"/><path d=\"M8.75 3.25v4.4l-4.1 7.1a1.5 1.5 0 0 0 1.3 2.25h8.1a1.5 1.5 0 0 0 1.3-2.25l-4.1-7.1v-4.4\"/><path d=\"M6.4 12.25h7.2\"/>",
    "globe": "<circle cx=\"10\" cy=\"10\" r=\"7.25\"/><path d=\"M2.75 10h14.5\"/><path d=\"M10 2.75c1.9 2 2.9 4.4 2.9 7.25s-1 5.25-2.9 7.25c-1.9-2-2.9-4.4-2.9-7.25s1-5.25 2.9-7.25z\"/>",
