      'rough skin': 'مشكلة خشونة البشرة',
      'scars': 'تحسين مظهر الندبات',
      'sensitivity': 'تهدئة البشرة الحساسة',
      'stretch marks': 'تحسين مظهر علامات التمدد',
      'sun protection': 'الحماية من الشمس',
      'sweating': 'التحكم في التعرق',
